public static boolean isMobilePhone(String phoneNo) {
        // 手机验证码规则，首位为1，后面10个数字
        String regExp = "^1\\d{10}$";
        return matches(regExp, phoneNo);
    }

private CommunicationEventMessage buildCommunicationEventMessage(String verificationCode, ShortMessageTypeEnum verificationType, String mobile) {
        CommunicationEventMessage communicationEventMessage = new CommunicationEventMessage();
        if (verificationType == ShortMessageTypeEnum.DEFAULT) {
            communicationEventMessage.setTplCode(defaultTempate);
            String params = "{\"params\":{\"code\":\"" + verificationCode + "\"}}";
            communicationEventMessage.setParams(params);
        } else {
            communicationEventMessage.setTplCode(normalTemplate);
            String params = "{\"params\":{\"captcha\":\"" + verificationCode + "\"}}";
            communicationEventMessage.setParams(params);
        }
        communicationEventMessage.setRecvAcct(String.format("[%s]", mobile));
        communicationEventMessage.setDeptCode(DeptCodes.WRL);
        communicationEventMessage.setChannel(CommonEnums.CHANNEL_EMAIL.getKey());
        return communicationEventMessage;
    }
